import { Component } from '@angular/core';
import { SteeringGraphComponent, config } from "@src/gui/services/steering/SteeringGraphComponent";
import {
  GemLineChartData,
  GemLineChartDataBuilder,
  GemLineChartEntry,
  GemLineChartEntryBuilder
} from '@umlp/charts';

@Component({
  standalone: true,
  imports: [
    ...config.imports,
  ],
  selector: config.selector,
  templateUrl: config.templateUrl,
  styles: config.styles,
  styleUrls: config.styleUrls
})
export class SteeringGraph extends SteeringGraphComponent {

  public override getSteeringGraphData(): GemLineChartData {
    if (!this.values) {
      return null;
    }
    const labels: string[] = this.values.map(v => this.formatTimestampLabel(v.getTimestamp()));
    const entries: GemLineChartEntry[] = [];
    const angleEntry: GemLineChartEntry = new GemLineChartEntryBuilder()
        .data(this.values.map(v => v.getData().getAngle()))
        .label(`Angle`)
        .build();
    entries.push(angleEntry);

    return new GemLineChartDataBuilder()
        .labels(labels)
        .entries(entries)
        .build();
  }

  private formatTimestampLabel(timestamp: Date): string {
    return `${timestamp.toLocaleTimeString('en-US', { hour12: false })}.${timestamp.getMilliseconds()}`
  }

}
